// MaterialEditTest, the item groups (package I). See MaterialEditTest.cs. Vanilla rows, every item
// synthetic, images generated by R's TestImage; numbers only.
//   Run       MI1  an item x float, color, texture, shader (with its queue), renderer Enabled, keyword: set, the value on the material, undo, redo;
//                  save, scene.new, load, the values again.
//   RunFull   MI2  RebuildContent: the values again, the array kept; a shader name rebuilds, a value change does not.
//             MI3  duplicate: the array byte-equal, the values on both; delete, undo: revived unchanged.
//             MI5  two instances of one row: an edit reaches one.
//             MI7  after every edit of MI1's kinds the bundle material of the row (read through the catalog) is unchanged.
//             MI8  an edit on _Color: a colour change under it, a Timeline slot on it, the slot cleared, the edit removed: the edit's value while it
//                  exists, the field or slot value after; the slot stays effective. A field equal to the edit's value shows after the removal.
//             MIL  lifecycle rows and addressing: item.ref set keeps the array and what no longer matches is materialMissing; a renderer by
//                  path, "." on the instance, a repeated sibling with [k]; a type that does not act on items reads notImplemented.
//             MVE  writes Spike/out/maker/material_shaders_editor.json: the candidates and the property lists of five named shaders, what
//                  Tools/material_edit_player_check.py compares the player with (MV1, MV2, MV4).
//             MT4  (merge part) an item's texture edit and panel image merged into another scene: both entries come along, the images resolve, a save
//                  writes them.
using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using HS2Next;
using HS2Next.Content;
using HS2Next.Save;
using HS2Next.Scenes;
using HS2Next.Scenes.Runtime;
using Newtonsoft.Json.Linq;
using UnityEngine;
using UnityEngine.Rendering;
using static MakerTestKit;

public static partial class MaterialEditTest
{
    const int BedRow = 89, SphereRow = 590, BoardRow = 975;

    static partial void QuickItems(McHost h)
    {
        if (Want("MI1")) Guard("MI1 round trips on an item", () => Mi1(h));
    }

    static partial void FullItems(McHost h)
    {
        if (Want("MI2")) Guard("MI2 a rebuild", () => Mi2(h));
        if (Want("MI3")) Guard("MI3 duplicate, delete, undo", () => Mi3(h));
        if (Want("MI5")) Guard("MI5 two instances of one row", () => Mi5(h));
        if (Want("MI7")) Guard("MI7 the bundle material stays", () => Mi7(h));
        if (Want("MI8")) Guard("MI8 fields and slots under an edit", () => Mi8(h));
        if (Want("MIL")) Guard("MIL lifecycle and addressing", () => Mil(h));
        if (Want("MIQ")) Guard("MIQ a queue on an item", () => Miq(h));
        if (Want("MT4")) Guard("MT4 scene merge", () => Mt4Merge(h));
        if (Want("MVE")) Guard("MVE the Editor's lists for the player check", MvEditorList);
    }

    // A queue means the same on every target: on an item the shadow switch follows it and a clear gives it back. The fog stamp needs a mapped
    // material whose original has fog variants; a vanilla item's have none, so FollowQueue's stamp is shown on a character's, through the shared writer.
    static void Miq(McHost h)
    {
        h.Ok(new { cmd = "scene.new" }, "MIQ scene.new");
        string id = AddItem(h, SphereRow);
        var cand = MaterialShaders.All.FirstOrDefault(c => c.Keywords.Contains(ShaderMap.ReceiveShadowsOff) && c.Queue <= 2500);
        if (!Check("MIQ a candidate with the shadow switch", cand != null)) return;
        string mat = ItemOf(h, id).MaterialEdits.Target.Materials.First().Name;
        h.Ok(new { cmd = "item.materials.set", key = id, type = "shader", material = mat, shader = cand.Name }, "MIQ the swap");
        h.Rt.ApplyNow();
        Material M() => ItemMat(h, id, mat);
        bool On() => M().IsKeywordEnabled(ShaderMap.ReceiveShadowsOff);
        int q0 = M().renderQueue;
        Check("MIQ the switch off at the default queue", !On(), q0.ToString());
        h.Ok(new { cmd = "item.materials.set", key = id, type = "shader", material = mat, renderQueue = 3000 }, "MIQ a queue over 2500");
        h.Rt.ApplyNow();
        Check("MIQ over 2500: the switch on", On() && M().renderQueue == 3000, M().renderQueue.ToString());
        h.Ok(new { cmd = "item.materials.set", key = id, type = "shader", material = mat, renderQueue = 2000 }, "MIQ a queue under 2500");
        h.Rt.ApplyNow();
        Check("MIQ under 2500: the switch off", !On() && M().renderQueue == 2000, M().renderQueue.ToString());
        h.Ok(new { cmd = "item.materials.set", key = id, type = "shader", material = mat, renderQueue = 3000 }, "MIQ over 2500 again");
        h.Rt.ApplyNow();
        h.Ok(new { cmd = "item.materials.set", key = id, type = "shader", material = mat, renderQueue = (object)null }, "MIQ the queue cleared");
        h.Rt.ApplyNow();
        Check("MIQ the queue cleared: the queue and the switch back", !On() && M().renderQueue == q0, M().renderQueue + " " + On());
        h.Ok(new { cmd = "scene.new" }, "MIQ scene.new");

        string key = LoadTarget(h);
        Material fogged = null;
        foreach (var r in Real(h, key).Root.GetComponentsInChildren<Renderer>(true))
            foreach (var m in r.sharedMaterials)
                if (!fogged && m && m.HasProperty(HS2FogFeature.ModesProperty) && ShaderMap.MappedFrom(m) is Shader s && HS2FogFeature.ModesOf(s) != 0) fogged = m;
        if (Check("MIQ a mapped material whose original has fog variants", fogged != null))
        {
            int q = fogged.renderQueue, modes = HS2FogFeature.ModesOf(ShaderMap.MappedFrom(fogged));
            MaterialWrites.SetQueue(fogged, 3000, null);
            Check("MIQ fog: over 2500 the stamp is the original's", (int)fogged.GetFloat(HS2FogFeature.ModesProperty) == modes, fogged.GetFloat(HS2FogFeature.ModesProperty) + " / " + modes);
            MaterialWrites.SetQueue(fogged, 2000, null);
            Check("MIQ fog: under 2500 it is 0", fogged.GetFloat(HS2FogFeature.ModesProperty) == 0f, fogged.GetFloat(HS2FogFeature.ModesProperty).ToString());
            MaterialWrites.SetQueue(fogged, q, null);
        }
        h.Ok(new { cmd = "scene.new" }, "MIQ scene.new");
    }

    // ---- helpers

    public static ItemRealization ItemOf(McHost h, string id) => h.Rt.FindItem(id);
    public static ItemNodeState ItemState(McHost h, string id) => h.Session.Model.Find(id)?.State as ItemNodeState;

    public static string AddItem(McHost h, int no)
    {
        var r = h.Ok(new { cmd = "item.add", no }, "item.add " + no);
        h.Rt.ApplyNow();
        return (string)r["key"] ?? (string)r["added"]?[0]?["key"];
    }

    static readonly ExecuteOptions UserEdit = new ExecuteOptions { Source = CommandSource.User, Label = "Material edit" };

    /// <summary>The item's array set as the ops do, one entry.</summary>
    public static void SetItemArray(McHost h, string id, List<MaterialOverride> next)
    {
        var r = h.Session.Set(id, "item.materialOverrides", next, UserEdit);
        if (r.Status == CommandStatus.Error) Check("the array is accepted", false, r.ToString());
        h.Rt.ApplyNow();
    }

    /// <summary>One edit on the item's current array; false when it changed nothing.</summary>
    public static bool ItemEdit(McHost h, string id, MaterialEdit e)
    {
        var list = ItemState(h, id).MaterialOverrides;
        var next = MaterialEdits.Set(list, e);
        if (ReferenceEquals(next, list)) return false;
        SetItemArray(h, id, next);
        return true;
    }

    static Material ItemMat(McHost h, string id, string name) => ItemOf(h, id).MaterialEdits.Target.Named(name).Select(e => e.Material).FirstOrDefault();

    /// <summary>The first slot of the item with a property of the type, not a fallback's fixed one.</summary>
    static Material PickItemMaterial(McHost h, string id, Func<Material, bool> ok)
    {
        foreach (var e in ItemOf(h, id).MaterialEdits.Target.Materials)
            if (e.Material && !ShaderMap.IsFallback(e.Material) && ok(e.Material)) return e.Material;
        return null;
    }

    static MaterialBaseline.Value? ItemBase(McHost h, string id, Material m, MaterialMember kind, string prop)
    {
        var t = ItemOf(h, id).MaterialEdits.Target;
        if (t.Baseline.TryGet(m, kind, prop, out var v)) return v;
        return MaterialBaseline.TryRead(m, kind, prop, out v) ? v : (MaterialBaseline.Value?)null;
    }

    sealed class ItemCase
    {
        public string Type, What, Material, Property;
        public Func<MaterialEdit> Make;
        public Func<string> Read;
        public string After;
    }

    static string MatName(Material m) => MeKey.Format(m.name);

    /// <summary>The six edits on an item: what its slots offer.</summary>
    static List<ItemCase> ItemCases(McHost h, string id, string image)
    {
        var l = new List<ItemCase>();
        var fm = PickItemMaterial(h, id, m => PickProperty(m, ShaderPropertyType.Float, ShaderPropertyType.Range) != null);
        if (fm)
        {
            string prop = PickProperty(fm, ShaderPropertyType.Float, ShaderPropertyType.Range), mat = MatName(fm);
            float was = fm.GetFloat(prop), to = was > 0.5f ? was - 0.25f : was + 0.25f;
            l.Add(new ItemCase
            {
                Type = "float", What = mat + " " + prop, Material = mat, Property = prop, After = Text(to),
                Make = () => MaterialEdit.Float(mat, prop.Substring(1), to, ItemBase(h, id, ItemMat(h, id, mat), MaterialMember.Float, prop)?.Float),
                Read = () => Text(ItemMat(h, id, mat).GetFloat(prop)),
            });
        }
        var cm = PickItemMaterial(h, id, m => PickProperty(m, ShaderPropertyType.Color, ShaderPropertyType.Color) != null);
        if (cm)
        {
            string prop = PickProperty(cm, ShaderPropertyType.Color, ShaderPropertyType.Color), mat = MatName(cm);
            var to = new Color(0.25f, 0.5f, 0.75f, 1f);
            l.Add(new ItemCase
            {
                Type = "color", What = mat + " " + prop, Material = mat, Property = prop, After = Text(Near(to)),
                Make = () =>
                {
                    var b = ItemBase(h, id, ItemMat(h, id, mat), MaterialMember.Color, prop);
                    return MaterialEdit.ColorOf(mat, prop.Substring(1), C4(to), b.HasValue ? C4(b.Value.Color) : (Color4?)null);
                },
                Read = () => Text(Near(ItemMat(h, id, mat).GetColor(prop))),
            });
        }
        var tm = PickItemMaterial(h, id, m => PickProperty(m, ShaderPropertyType.Texture, ShaderPropertyType.Texture) != null);
        if (tm)
        {
            string prop = PickProperty(tm, ShaderPropertyType.Texture, ShaderPropertyType.Texture), mat = MatName(tm);
            var off = new Vector2(0.125f, 0.25f);
            var sc = new Vector2(2f, 3f);
            l.Add(new ItemCase
            {
                Type = "texture", What = mat + " " + prop, Material = mat, Property = prop, After = "8x8 " + Text(off) + " " + Text(sc),
                Make = () => MaterialEdit.Texture(mat, prop.Substring(1)).WithImage(image).WithOffset(new Vec2(off.x, off.y)).WithScale(new Vec2(sc.x, sc.y)),
                Read = () =>
                {
                    var m = ItemMat(h, id, mat);
                    var tex = m.GetTexture(prop);
                    return (tex ? tex.width + "x" + tex.height : "none") + " " + Text(m.GetTextureOffset(prop)) + " " + Text(m.GetTextureScale(prop));
                },
            });
        }
        var t = ItemOf(h, id).MaterialEdits.Target;
        var rr = t.Renderers.FirstOrDefault(r => r && r.enabled);
        if (rr)
        {
            string path = t.PathOf(rr);
            l.Add(new ItemCase
            {
                Type = "renderer", What = path, After = "off",
                Make = () => MaterialEdit.RendererEnabled(path, 0, 1),
                Read = () => FindRenderer(h, id, path).enabled ? "on" : "off",
            });
        }
        var km = PickItemMaterial(h, id, m => m.shader.name.StartsWith("HS2Next/", StringComparison.Ordinal) && Keyword(m) != null);
        if (km)
        {
            string kw = Keyword(km), mat = MatName(km);
            bool was = km.IsKeywordEnabled(kw);
            l.Add(new ItemCase
            {
                Type = "keyword", What = mat + " " + kw, Material = mat, Property = kw, After = !was ? "on" : "off",
                Make = () => MaterialEdit.Keyword(mat, kw.Substring(1), !was, was),
                Read = () => ItemMat(h, id, mat).IsKeywordEnabled(kw) ? "on" : "off",
            });
        }
        var sm = PickItemMaterial(h, id, m => m.shader.name.StartsWith("HS2Next/", StringComparison.Ordinal));
        if (sm)
        {
            string mat = MatName(sm), cur = sm.shader.name;
            // a shader that keeps what the other cases name, so they still act after the swap
            var cand = MaterialShaders.All.First(c => c.Name != cur && c.Name.Contains("AIT") && l.Where(x => x.Property != null).All(x => x.Type == "keyword" ? c.Keywords.Contains(x.Property) : c.Shader.FindPropertyIndex(x.Property) >= 0));
            l.Add(new ItemCase
            {
                Type = "shader", What = mat + " -> " + cand.Name, After = cand.Name + " 3100",
                Make = () => MaterialEdit.ShaderItem(mat).WithShader(cand.Name, cur).WithQueue(3100, ItemMat(h, id, mat).renderQueue),
                Read = () => { var m = ItemMat(h, id, mat); return m.shader.name + " " + m.renderQueue; },
            });
        }
        return l;
    }

    static Renderer FindRenderer(McHost h, string id, string path)
    {
        var l = new List<Renderer>();
        ItemOf(h, id).MaterialEdits.Target.SelectRenderers(path, l);
        return l.FirstOrDefault();
    }

    // ---- MI1

    static void Mi1(McHost h)
    {
        h.Ok(new { cmd = "scene.new" }, "MI1 scene.new");
        string id = AddItem(h, BedRow);
        string image = TestImage(h, new Color(0.1f, 0.9f, 0.2f, 1f));
        var cases = ItemCases(h, id, image);
        Info("MI1 cases: " + string.Join(", ", cases.Select(c => c.Type + " " + c.What)));
        Check("MI1 the six types ran", cases.Select(c => c.Type).Distinct().Count() == 6, string.Join(", ", cases.Select(c => c.Type)));
        var read = new Dictionary<ItemCase, string>();
        foreach (var c in cases)
        {
            string what = "MI1 " + c.Type;
            read[c] = c.Read();
            if (!Check(what + ": set makes an entry", ItemEdit(h, id, c.Make()))) continue;
            Check(what + ": on the material", c.Read() == c.After, c.Read() + " want " + c.After);
            Undo(h, what + ": undo");
            Check(what + ": undo gives the value before", c.Read() == read[c], c.Read() + " want " + read[c]);
            Redo(h, what + ": redo");
            Check(what + ": redo gives the value", c.Read() == c.After, c.Read() + " want " + c.After);
        }
        var save = h.Ok(new { cmd = "scene.save", name = "mi1", overwrite = true, thumb = "placeholder", clock = "2026-11-05T00:00:00Z" }, "MI1 scene.save");
        string json = Json(ItemState(h, id).MaterialOverrides);
        h.Ok(new { cmd = "scene.new" }, "MI1 scene.new");
        h.Ok(new { cmd = "scene.load", path = (string)save["path"] }, "MI1 scene.load");
        h.Rt.ApplyNow();
        Check("MI1 the array after load", Json(ItemState(h, id).MaterialOverrides) == json);
        foreach (var c in cases)
            Check("MI1 " + c.Type + ": on the material after load", c.Read() == c.After, c.Read() + " want " + c.After);
        h.Ok(new { cmd = "scene.new" }, "MI1 scene.new");
    }

    // ---- MI2

    static void Rebuild(McHost h, ItemRealization it) =>
        typeof(SceneRuntime).GetMethod("RebuildContent", System.Reflection.BindingFlags.Instance | System.Reflection.BindingFlags.NonPublic).Invoke(h.Rt, new object[] { it });

    static void Mi2(McHost h)
    {
        h.Ok(new { cmd = "scene.new" }, "MI2 scene.new");
        string id = AddItem(h, BedRow);
        string image = TestImage(h, new Color(0.3f, 0.2f, 0.7f, 1f));
        var cases = ItemCases(h, id, image).Where(c => c.Type != "shader").ToList();
        foreach (var c in cases) ItemEdit(h, id, c.Make());
        string json = Json(ItemState(h, id).MaterialOverrides);
        var inst = ItemOf(h, id).Instance;
        foreach (var c in cases) Check("MI2 " + c.Type + " before the rebuild", c.Read() == c.After, c.Read());
        Check("MI2 value edits rebuilt nothing", ItemOf(h, id).Instance == inst);
        Rebuild(h, ItemOf(h, id));
        h.Rt.ApplyNow();
        Check("MI2 the rebuild made a new instance", ItemOf(h, id).Instance != inst);
        Check("MI2 the array stays", Json(ItemState(h, id).MaterialOverrides) == json);
        foreach (var c in cases) Check("MI2 " + c.Type + " after the rebuild", c.Read() == c.After, c.Read() + " want " + c.After);
        inst = ItemOf(h, id).Instance;
        var sm = PickItemMaterial(h, id, m => m.shader.name.StartsWith("HS2Next/", StringComparison.Ordinal));
        string mat = MatName(sm), cur = sm.shader.name;
        var cand = MaterialShaders.All.First(c => c.Name != cur && c.Name.Contains("AIT"));
        ItemEdit(h, id, MaterialEdit.ShaderItem(mat).WithQueue(3001, sm.renderQueue));
        Check("MI2 a queue is a value: no rebuild", ItemOf(h, id).Instance == inst && ItemMat(h, id, mat).renderQueue == 3001, ItemMat(h, id, mat).renderQueue.ToString());
        ItemEdit(h, id, MaterialEdit.ShaderItem(mat).WithShader(cand.Name, cur));
        Check("MI2 a shader name rebuilds", ItemOf(h, id).Instance != inst && ItemMat(h, id, mat).shader.name == cand.Name, ItemMat(h, id, mat).shader.name);
        Check("MI2 the item's queue holds after the swap", ItemMat(h, id, mat).renderQueue == 3001, ItemMat(h, id, mat).renderQueue.ToString());
        foreach (var c in cases.Where(c => c.Type == "renderer")) Check("MI2 a renderer item after the shader rebuild", c.Read() == c.After, c.Read());
        var key = MeKey.Shader(mat);
        SetItemArray(h, id, MaterialEdits.Remove(ItemState(h, id).MaterialOverrides, key));
        Check("MI2 removing the shader item brings the shader back", ItemMat(h, id, mat).shader.name == cur, ItemMat(h, id, mat).shader.name);
        Undo(h, "MI2 undo the removal");
        Check("MI2 undo swaps again", ItemMat(h, id, mat).shader.name == cand.Name, ItemMat(h, id, mat).shader.name);
        h.Ok(new { cmd = "scene.new" }, "MI2 scene.new");
    }

    // ---- MI3

    static void Mi3(McHost h)
    {
        h.Ok(new { cmd = "scene.new" }, "MI3 scene.new");
        string id = AddItem(h, BedRow);
        string image = TestImage(h, new Color(0.7f, 0.2f, 0.3f, 1f));
        var cases = ItemCases(h, id, image).Where(c => c.Type == "float" || c.Type == "color" || c.Type == "texture").ToList();
        foreach (var c in cases) ItemEdit(h, id, c.Make());
        string json = Json(ItemState(h, id).MaterialOverrides);
        var dup = h.App.Ops.Duplicate(new[] { id });
        h.Rt.ApplyNow();
        string copy = dup.NewIds?.FirstOrDefault();
        if (!Check("MI3 duplicate", dup.Ok && copy != null, dup.Message)) return;
        Check("MI3 the copy's array is byte-equal", Json(ItemState(h, copy).MaterialOverrides) == json);
        var mine = new HashSet<Material>(ItemOf(h, id).MaterialEdits.Target.Materials.Select(e => e.Material));
        Check("MI3 the copy has its own materials", ItemOf(h, copy).MaterialEdits.Target.Materials.All(e => !mine.Contains(e.Material)));
        foreach (var c in cases) Check("MI3 " + c.Type + " on the source", c.Read() == c.After, c.Read());
        foreach (var c in cases)
        {
            // the same read on the copy
            var m = c.Material != null ? ItemMat(h, copy, c.Material) : null;
            string got = c.Type == "float" ? Text(m.GetFloat(c.Property)) : c.Type == "color" ? Text(Near(m.GetColor(c.Property))) : null;
            if (got != null) Check("MI3 " + c.Type + " on the copy", got == c.After, got + " want " + c.After);
        }
        var del = h.App.Ops.Delete(new[] { id });
        h.Rt.ApplyNow();
        Check("MI3 delete", del.Ok, del.Message);
        Undo(h, "MI3 undo the delete");
        Check("MI3 undo revives the array", Json(ItemState(h, id).MaterialOverrides) == json);
        foreach (var c in cases) Check("MI3 " + c.Type + " revived", c.Read() == c.After, c.Read());
        h.Ok(new { cmd = "scene.new" }, "MI3 scene.new");
    }

    // ---- MI5

    static void Mi5(McHost h)
    {
        h.Ok(new { cmd = "scene.new" }, "MI5 scene.new");
        string a = AddItem(h, BedRow), b = AddItem(h, BedRow);
        string image = TestImage(h, new Color(0.2f, 0.3f, 0.9f, 1f));
        var before = BedPrint(h, b);
        foreach (var c in ItemCases(h, a, image))
        {
            if (c.Type == "renderer") continue;
            ItemEdit(h, a, c.Make());
            Check("MI5 " + c.Type + " reaches its item", c.Read() == c.After, c.Read() + " want " + c.After);
            Check("MI5 " + c.Type + " does not reach the other instance", BedPrint(h, b) == before, Short(BedPrint(h, b)));
        }
        Check("MI5 the instances share no material", !ItemOf(h, a).MaterialEdits.Target.Materials.Select(e => e.Material).Intersect(ItemOf(h, b).MaterialEdits.Target.Materials.Select(e => e.Material)).Any());
        string third = AddItem(h, BedRow);
        Check("MI5 a new instance of the row starts from the bundle's values", BedPrint(h, third) == before, Short(BedPrint(h, third)));
        h.Ok(new { cmd = "scene.new" }, "MI5 scene.new");
    }

    /// <summary>Every declared value of a material as text.</summary>
    public static string Print(Material m)
    {
        var sb = new System.Text.StringBuilder(m.name + " " + (m.shader ? m.shader.name : "") + " q" + m.renderQueue + " [" + string.Join(" ", m.shaderKeywords.OrderBy(k => k, StringComparer.Ordinal)) + "]");
        var sh = m.shader;
        for (int i = 0; sh && i < sh.GetPropertyCount(); i++)
        {
            string n = sh.GetPropertyName(i);
            switch (sh.GetPropertyType(i))
            {
                case ShaderPropertyType.Color: sb.Append(' ').Append(n).Append('=').Append(Text(m.GetColor(n))); break;
                case ShaderPropertyType.Vector: { var v = m.GetVector(n); sb.Append(' ').Append(n).Append('=').Append(Text(v.x)).Append(Text(v.y)).Append(Text(v.z)).Append(Text(v.w)); break; }
                case ShaderPropertyType.Texture:
                    if (sh.GetPropertyTextureDimension(i) == TextureDimension.Tex2D) { var t = m.GetTexture(n); sb.Append(' ').Append(n).Append('=').Append(t ? t.name : "-").Append(Text(m.GetTextureOffset(n))).Append(Text(m.GetTextureScale(n))); }
                    break;
                case ShaderPropertyType.Int: sb.Append(' ').Append(n).Append('=').Append(m.GetInteger(n)); break;
                default: sb.Append(' ').Append(n).Append('=').Append(Text(m.GetFloat(n))); break;
            }
        }
        return sb.ToString();
    }

    static string BedPrint(McHost h, string id) => string.Join("\n", ItemOf(h, id).MaterialEdits.Target.Materials.Select(e => Print(e.Material)));

    // ---- MI7

    static void Mi7(McHost h)
    {
        h.Ok(new { cmd = "scene.new" }, "MI7 scene.new");
        string id = AddItem(h, BedRow);
        var it = ItemOf(h, id);
        var prefab = h.Rt.Services.Catalog.LoadAsset<GameObject>(it.Row);
        var bundle = prefab.GetComponentsInChildren<Renderer>(true).SelectMany(r => r.sharedMaterials).Where(m => m).Distinct().ToList();
        if (!Check("MI7 the row's bundle materials", bundle.Count > 0)) return;
        var owned = new HashSet<Material>(it.MaterialEdits.Target.Materials.Select(e => e.Material));
        Check("MI7 no bundle material is in the index", bundle.All(m => !owned.Contains(m)));
        string before = string.Join("\n", bundle.Select(Print));
        string image = TestImage(h, new Color(0.9f, 0.9f, 0.1f, 1f));
        foreach (var c in ItemCases(h, id, image))
        {
            ItemEdit(h, id, c.Make());
            Check("MI7 " + c.Type + ": the bundle material is unchanged", string.Join("\n", bundle.Select(Print)) == before);
        }
        h.Ok(new { cmd = "scene.new" }, "MI7 scene.new");
        Check("MI7 after the scene went: the bundle material is unchanged", string.Join("\n", bundle.Select(Print)) == before);
    }

    // ---- MI8

    static void Mi8(McHost h)
    {
        h.Ok(new { cmd = "scene.new" }, "MI8 scene.new");
        string id = AddItem(h, BedRow);
        var it = ItemOf(h, id);
        var cm = PickItemMaterial(h, id, m => m.HasProperty("_Color"));
        if (!Check("MI8 a slot with _Color", cm)) return;
        string mat = MatName(cm);
        var edit = new Color(0.1f, 0.6f, 0.3f, 1f);
        Color Live() => ItemMat(h, id, mat).GetColor("_Color");
        bool Is(Color a, Color b) => Mathf.Abs(a.r - b.r) < 1e-4f && Mathf.Abs(a.g - b.g) < 1e-4f && Mathf.Abs(a.b - b.b) < 1e-4f;
        void Field(Color c) { h.Session.Set(id, "item.colors[0].main", C4(c)); h.Rt.ApplyNow(); }
        var field0 = ItemState(h, id).Colors[0].Main;
        var key = MeKey.Property("color", mat, "Color");
        ItemEdit(h, id, MaterialEdit.ColorOf(mat, "Color", C4(edit), C4(Live())));
        Check("MI8 the edit shows", Is(Live(), edit), Live().ToString());
        var red = new Color(0.8f, 0.1f, 0.1f, 1f);
        Field(red);
        Check("MI8 a colour change: the edit stays on top", Is(Live(), edit), Live().ToString());
        var slot = h.Rt.Overrides.Acquire(HS2Next.Scenes.Overrides.OverrideLayer.TimelineOwner, id, "item.colors[0].main");
        for (int i = 0; i < 5; i++)
        {
            slot.Set(0.2 + 0.1 * i, 0.3, 0.4, 1.0);
            h.Rt.ApplyNow();
            Check("MI8 a colour slot playing: the edit's value", Is(Live(), edit), Live().ToString());
        }
        Check("MI8 the slot is not suspended", slot.IsWinning && slot.HasValue);
        SetItemArray(h, id, MaterialEdits.Remove(ItemState(h, id).MaterialOverrides, key));
        var last = new Color(0.6f, 0.3f, 0.4f, 1f);
        Check("MI8 the edit removed under the slot: the slot's value", Is(Live(), last), Live().ToString());
        ItemEdit(h, id, MaterialEdit.ColorOf(mat, "Color", C4(edit), C4(Live())));
        slot.Release();
        h.Rt.ApplyNow();
        Check("MI8 the slot cleared under an edit: the edit's value", Is(Live(), edit), Live().ToString());
        SetItemArray(h, id, MaterialEdits.Remove(ItemState(h, id).MaterialOverrides, key));
        Check("MI8 the edit removed: the field's value", Is(Live(), red), Live().ToString());
        // a field that took exactly the edit's value under it
        ItemEdit(h, id, MaterialEdit.ColorOf(mat, "Color", C4(edit), C4(Live())));
        Field(edit);
        SetItemArray(h, id, MaterialEdits.Remove(ItemState(h, id).MaterialOverrides, key));
        Check("MI8 a field equal to the edit stays after the removal", Is(Live(), edit), Live().ToString());
        Field(UnityObjects.C(field0));
        Check("MI8 no edit: the field writes as ever", Is(Live(), UnityObjects.C(field0)), Live().ToString());
        h.Ok(new { cmd = "scene.new" }, "MI8 scene.new");
    }

    // ---- MIL

    static void Mil(McHost h)
    {
        h.Ok(new { cmd = "scene.new" }, "MIL scene.new");
        string id = AddItem(h, BedRow);
        var t = ItemOf(h, id).MaterialEdits.Target;
        var paths = t.Renderers.Select(t.PathOf).ToList();
        Check("MIL paths are unique", paths.Distinct().Count() == paths.Count, string.Join(", ", paths));
        foreach (var r in t.Renderers)
        {
            var l = new List<Renderer>();
            t.SelectRenderers(t.PathOf(r), l);
            Check("MIL a path finds its renderer", l.Count == 1 && l[0] == r, t.PathOf(r));
        }
        var root = new GameObject("mil_root").transform;
        var a = new GameObject("x").transform; a.SetParent(root);
        var b = new GameObject("x").transform; b.SetParent(root);
        var c = new GameObject("y").transform; c.SetParent(b);
        Check("MIL \".\" is the instance", ItemMaterialEdits.PathIn(root, root) == ".");
        Check("MIL [k] on every repeated sibling", ItemMaterialEdits.PathIn(root, a) == "x[0]" && ItemMaterialEdits.PathIn(root, c) == "x[1]/y", ItemMaterialEdits.PathIn(root, a) + " " + ItemMaterialEdits.PathIn(root, c));
        UnityEngine.Object.DestroyImmediate(root.gameObject);

        var fm = PickItemMaterial(h, id, m => PickProperty(m, ShaderPropertyType.Float, ShaderPropertyType.Range) != null);
        string prop = PickProperty(fm, ShaderPropertyType.Float, ShaderPropertyType.Range), mat = MatName(fm);
        ItemEdit(h, id, MaterialEdit.Float(mat, prop.Substring(1), fm.GetFloat(prop) + 0.125f, fm.GetFloat(prop)));
        var item = ItemState(h, id).MaterialOverrides.Last();
        Check("MIL the item applies", ItemOf(h, id).MaterialEdits.Target.Status(item).Applied);
        string json = Json(ItemState(h, id).MaterialOverrides);
        var r0 = h.Session.Set(id, "item.ref", ContentId.Vanilla(SphereRow).ToString(), UserEdit);
        h.Rt.ApplyNow();
        Check("MIL item.ref set: the array stays", r0.Status != CommandStatus.Error && Json(ItemState(h, id).MaterialOverrides) == json, r0.ToString());
        var st = ItemOf(h, id).MaterialEdits.Target.Status(item);
        Check("MIL a name that no longer matches reads materialMissing", st.Status == MaterialStatus.MaterialMissing, st.Status);
        var odd = new List<MaterialOverride>(ItemState(h, id).MaterialOverrides) { new MeCopy { Material = mat, CopyName = "c" } };
        Check("MIL a copy item does not act on an item", ItemOf(h, id).MaterialEdits.Target.Status(odd.Last()).Status == MaterialStatus.NotImplemented);
        h.Ok(new { cmd = "scene.new" }, "MIL scene.new");
    }

    // ---- MVE

    static readonly string[] NamedShaders = { "AIT Clothes", "AIT Item", "Hanmen", "Standard", "Skin" };

    static void MvEditorList()
    {
        MaterialShaders.Reset();
        var all = MaterialShaders.All;
        var cands = new JArray();
        foreach (var c in all)
            cands.Add(new JObject { ["name"] = c.Name, ["family"] = c.Family, ["queue"] = c.Queue, ["keywords"] = new JArray(c.Keywords.Cast<object>().ToArray()) });
        var shaders = new JObject();
        foreach (var part in NamedShaders)
        {
            var c = all.FirstOrDefault(x => x.Name.Contains(part) && !shaders.ContainsKey(x.Name));
            if (c == null) { Warn("MVE", "no candidate holds " + part); continue; }
            var names = new JArray();
            for (int i = 0; i < c.Shader.GetPropertyCount(); i++)
            {
                string n = c.Shader.GetPropertyName(i);
                if (!names.Any(x => (string)x == n)) names.Add(n);
            }
            shaders[c.Name] = names;
        }
        var doc = new JObject { ["candidates"] = cands, ["shaders"] = shaders };
        File.WriteAllText(Path.Combine(OutDir, "material_shaders_editor.json"), doc.ToString(Newtonsoft.Json.Formatting.Indented), new System.Text.UTF8Encoding(false));
        Check("MVE the lists are written", all.Count > 0 && shaders.Count >= 5, all.Count + " candidates, " + shaders.Count + " named shaders");
    }

    // ---- MT4, the merge part

    static void Mt4Merge(McHost h)
    {
        h.Ok(new { cmd = "scene.new" }, "MT4 scene.new");
        string id = AddItem(h, BoardRow);
        string image = TestImage(h, new Color(0.4f, 0.8f, 0.6f, 1f));
        string panel = TestImage(h, new Color(0.8f, 0.4f, 0.6f, 1f));
        var fm = PickItemMaterial(h, id, m => PickProperty(m, ShaderPropertyType.Texture, ShaderPropertyType.Texture) != null);
        if (!Check("MT4 a texture slot on the board", fm)) return;
        string prop = PickProperty(fm, ShaderPropertyType.Texture, ShaderPropertyType.Texture), mat = MatName(fm);
        ItemEdit(h, id, MaterialEdit.Texture(mat, prop.Substring(1)).WithImage(image));
        h.Session.Set(id, "item.panel", FileRef.FromRes(panel));
        h.Rt.ApplyNow();
        var save = h.Ok(new { cmd = "scene.save", name = "mt4_merge", overwrite = true, thumb = "placeholder", clock = "2026-11-05T00:00:00Z" }, "MT4 scene.save");
        string path = (string)save["path"];
        h.Ok(new { cmd = "scene.new" }, "MT4 scene.new");
        Check("MT4 a new scene has neither image", !h.Session.Model.File.Res.Contains(image) && !h.Session.Model.File.Res.Contains(panel));
        var r = h.App.Ops.ImportScene(path);
        h.Rt.ApplyNow();
        if (!Check("MT4 the merge", r.Ok && r.NewIds?.Count == 1, r.Message)) return;
        string copy = r.NewIds[0];
        Check("MT4 the texture edit's image came along", h.Session.Model.File.Res.Contains(image));
        Check("MT4 the panel's image came along", h.Session.Model.File.Res.Contains(panel));
        var tex = ItemMat(h, copy, mat).GetTexture(prop);
        Check("MT4 the merged item's edit resolves", tex && tex.width == 8, tex ? tex.width.ToString() : "none");
        Check("MT4 the merged panel resolves", ItemOf(h, copy).PanelSource != null, ItemOf(h, copy).PanelSource ?? "none");
        var again = h.Ok(new { cmd = "scene.save", name = "mt4_merged", overwrite = true, thumb = "placeholder", clock = "2026-11-05T00:00:00Z" }, "MT4 scene.save of the merged scene");
        using (var zip = System.IO.Compression.ZipFile.OpenRead((string)again["path"]))
        {
            var names = new HashSet<string>(zip.Entries.Select(e => e.FullName));
            Check("MT4 the saved file holds both entries", names.Contains(image) && names.Contains(panel), string.Join(", ", names.Where(n => n.StartsWith("res/", StringComparison.Ordinal))));
        }
        h.Ok(new { cmd = "scene.new" }, "MT4 scene.new");
    }
